{
  "name": "EMR-20电磁场强度探头",
  "name_en": "EMR-20 Field Strength Probe",
  "manufacturer": "Wandel & Goltermann",
  "description": "EMR-20是一种用于测量电磁场强度的场强探头，可输出现场测得的场强数值。它通常用于电磁兼容测试、辐射环境监测以及实验室中的电磁场分布测量。",
  "description_en": "The EMR-20 is a field strength probe used to measure electromagnetic field intensity and report the measured field value. It is typically used for EMC testing, radiated environment monitoring, and laboratory measurements of electromagnetic field distribution.",
  "tag_hints": [
    "electromagnetic field strength",
    "EMC testing",
    "field probe",
    "radiated field measurement",
    "field monitoring"
  ],
  "actions": [
    {
      "action_name": "setup",
      "description": "初始化并配置场强探头。",
      "description_en": "Initialize and configure the field strength probe."
    },
    {
      "action_name": "auto-readback",
      "description": "读取场强回读数据。",
      "description_en": "Read back the field strength measurement data."
    },
    {
      "action_name": "auto-read",
      "description": "读取场强数值。",
      "description_en": "Read the field strength value."
    }
  ]
}

